        fail();
    } catch (final NullPointerException ex) {
        // expected
        assertFalse(file.exists());
        assertFalse(lockFile.exists());
    } finally {
        IOUtils.closeQuietly(writer);
    }
    assertFalse(file.exists());
    assertFalse(lockFile.exists());
}

